-- Create employees present in Employee_Master_Data.xlsx but missing in the system.
BEGIN;

CREATE TEMP TABLE emp_new_in (
  employee_code text,
  full_name text,
  mobile text,
  gender text,
  date_of_birth text,
  preferred_joining_date text,
  marital_status text,
  religion text,
  languages text,
  emergency_contact_name text,
  emergency_contact_mobile text,
  emergency_contact_relation text,
  present_address1 text,
  present_address2 text,
  present_city text,
  present_district text,
  present_state text,
  present_country text,
  present_pincode text,
  permanent_address1 text,
  permanent_address2 text,
  permanent_city text,
  permanent_district text,
  permanent_state text,
  permanent_pincode text,
  aadhaar_number text,
  pan_number text,
  bank_name text,
  bank_branch text,
  bank_account_number text,
  bank_ifsc text,
  bank_account_holder text,
  father_name text,
  mother_name text,
  spouse_name text,
  education_level text,
  blood_group text,
  height text,
  weight text,
  chest text,
  uan text,
  epf_number text,
  esic_number text
) ON COMMIT DROP;


  employee_code, candidate_code, full_name, status, is_enabled, application_date,
  mobile, gender, date_of_birth, preferred_joining_date, marital_status, religion, languages,
  emergency_contact_name, emergency_contact_mobile, emergency_contact_relation,
  present_address1, present_address2, present_city, present_district, present_state, present_country, present_pincode,
  permanent_address1, permanent_address2, permanent_city, permanent_district, permanent_state, permanent_pincode,
  aadhaar_number, pan_number, bank_name, bank_branch, bank_account_number, bank_ifsc, bank_account_holder,
  other_info, physical_health, compliance
)
SELECT
  i.employee_code, 'CAN-E' || i.employee_code, COALESCE(i.full_name, ''), 'active', true, i.preferred_joining_date::date,
  COALESCE(CASE WHEN i.mobile IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.candidates x WHERE x.mobile = i.mobile) THEN i.mobile END, ''),
  COALESCE(i.gender, ''), i.date_of_birth::date, i.preferred_joining_date::date, COALESCE(i.marital_status, ''), COALESCE(i.religion, ''),
  COALESCE(i.languages::jsonb, '[]'::jsonb),
  COALESCE(i.emergency_contact_name, ''), COALESCE(i.emergency_contact_mobile, ''), COALESCE(i.emergency_contact_relation, ''),
  COALESCE(i.present_address1, ''), COALESCE(i.present_address2, ''), COALESCE(i.present_city, ''), COALESCE(i.present_district, ''), COALESCE(i.present_state, ''), COALESCE(i.present_country, ''), COALESCE(i.present_pincode, ''),
  COALESCE(i.permanent_address1, ''), COALESCE(i.permanent_address2, ''), COALESCE(i.permanent_city, ''), COALESCE(i.permanent_district, ''), COALESCE(i.permanent_state, ''), COALESCE(i.permanent_pincode, ''),
  COALESCE(CASE WHEN i.aadhaar_number IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.candidates x WHERE x.aadhaar_number = i.aadhaar_number) THEN i.aadhaar_number END, ''),
  COALESCE(i.pan_number, ''), COALESCE(i.bank_name, ''), COALESCE(i.bank_branch, ''), COALESCE(i.bank_account_number, ''), COALESCE(i.bank_ifsc, ''), COALESCE(i.bank_account_holder, ''),
  jsonb_strip_nulls(jsonb_build_object('father_name', i.father_name, 'mother_name', i.mother_name, 'spouse_name', i.spouse_name, 'education_level', i.education_level)),
  jsonb_strip_nulls(jsonb_build_object('blood_group', i.blood_group, 'height', i.height, 'weight', i.weight, 'chest', i.chest)),
  jsonb_strip_nulls(jsonb_build_object('uan', i.uan, 'epf_number', i.epf_number, 'esic_number', i.esic_number))
FROM emp_new_in i
WHERE NOT EXISTS (SELECT 1 FROM public.candidates c WHERE c.employee_code = i.employee_code);

COMMIT;
